#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/k_heap.h>

#define HEAP_SIZE (1024)
#define MALLOC_SIZE (100)
#define ALIGNMENT 4

K_HEAP_DEFINE(k_heap, HEAP_SIZE);

static void *block_list[2];

static void test_mheap_malloc_free(void)
{
	void *block;
	char *p;
	int i;

	block = k_heap_alloc(&k_heap, MALLOC_SIZE, K_NO_WAIT);
	zassert_not_null(block, "k_heap_alloc failed");

	/* test if memory is accessible */
	p = (char *)block;
	for (i = 0; i < MALLOC_SIZE; i++) {
		p[i] = (char)i;
	}

	k_heap_free(&k_heap, block);

	/* Verify that a second allocation gets the same block */
	block = k_heap_alloc(&k_heap, MALLOC_SIZE, K_NO_WAIT);
	zassert_not_null(block, "k_heap_alloc failed");
	zassert_equal(p, block, "2nd alloc didn't get the same block");

	k_heap_free(&k_heap, block);
}

static void test_mheap_calloc(void)
{
	void *block;
	char *p;
	int i;

	block = k_heap_calloc(&k_heap, 1, MALLOC_SIZE, K_NO_WAIT);
	zassert_not_null(block, "k_heap_calloc failed");

	/* test if memory is zeroed */
	p = (char *)block;
	for (i = 0; i < MALLOC_SIZE; i++) {
		zassert_equal(p[i], 0, "k_heap_calloc is not zeroed");
	}

	k_heap_free(&k_heap, block);
}

static void test_mheap_malloc_align4(void)
{
	block_list[0] = k_heap_alloc(&k_heap, MALLOC_SIZE, K_NO_WAIT);
	zassert_not_null(block_list[0], "k_heap_alloc failed");
	zassert_equal(((uintptr_t)block_list[0] % ALIGNMENT), 0,
			"k_heap_alloc is not aligned");

	block_list[1] = k_heap_alloc(&k_heap, MALLOC_SIZE, K_NO_WAIT);
	zassert_not_null(block_list[1], "k_heap_alloc failed");
	zassert_equal(((uintptr_t)block_list[1] % ALIGNMENT), 0,
			"k_heap_alloc is not aligned");

	k_heap_free(&k_heap, block_list[0]);
	k_heap_free(&k_heap, block_list[1]);
}

static void test_k_aligned_alloc(void)
{
	void *block1, *block2;

	block1 = k_heap_aligned_alloc(&k_heap, 8, 16, K_NO_WAIT);
	zassert_not_null(block1, "k_heap_aligned_alloc failed");
	zassert_equal(((uintptr_t)block1 % 8), 0,
			"k_heap_aligned_alloc is not aligned to 8");

	block2 = k_heap_aligned_alloc(&k_heap, 16, 32, K_NO_WAIT);
	zassert_not_null(block2, "k_heap_aligned_alloc failed");
	zassert_equal(((uintptr_t)block2 % 16), 0,
			"k_heap_aligned_alloc is not aligned to 16");

	k_heap_free(&k_heap, block1);
	k_heap_free(&k_heap, block2);
}

static void t_isr_malloc(void *p)
{
	void *block;

	block = k_heap_alloc(&k_heap, MALLOC_SIZE, K_NO_WAIT);
	zassert_not_null(block, "k_heap_alloc failed");
	k_heap_free(&k_heap, block);
}

static void test_malloc_in_isr(void)
{
	irq_offload(t_isr_malloc, NULL);
}

static void t_thread_malloc(void *p1, void *p2, void *p3)
{
	void *block;

	block = k_heap_alloc(&k_heap, MALLOC_SIZE, K_NO_WAIT);
	zassert_not_null(block, "k_heap_alloc failed");
	k_heap_free(&k_heap, block);
}

K_THREAD_STACK_DEFINE(tstack, 512);
static struct k_thread tthread;

static void test_malloc_in_thread(void)
{
	k_tid_t tid = k_thread_create(&tthread, tstack,
			K_THREAD_STACK_SIZEOF(tstack),
			t_thread_malloc,
			NULL, NULL, NULL,
			K_PRIO_PREEMPT(0), 0, K_NO_WAIT);
	k_thread_join(tid, K_FOREVER);
}

void test_main(void)
{
	ztest_test_suite(mheap_api,
			 ztest_unit_test(test_k_aligned_alloc),
			 ztest_unit_test(test_malloc_in_isr),
			 ztest_unit_test(test_malloc_in_thread),
			 ztest_unit_test(test_mheap_calloc),
			 ztest_unit_test(test_mheap_malloc_align4),
			 ztest_unit_test(test_mheap_malloc_free)
			 );
	ztest_run_test_suite(mheap_api);
}
